// Runtime schema, generated by tools/gen-schema.mjs (see plan §4).

export type StyleName = "LLVM" | "Google" | "Chromium" | "Mozilla" | "WebKit" | "Microsoft" | "GNU";

export type ScalarKind = "bool" | "int" | "uint" | "string";

export type OptionType =
  | { kind: "scalar"; scalar: ScalarKind }
  | { kind: "enum"; values: string[] }
  | { kind: "map"; children: Field[] }
  | { kind: "list"; item: "string" }
  | { kind: "list"; item: "struct"; fields: Field[] };

export type Field = { key: string; type: OptionType };

export type OptionDef = {
  key: string;
  type: OptionType;
  deprecated: boolean;
  defaults: Partial<Record<StyleName, unknown>>;
};

export type SchemaCore = {
  version: string;
  build: string;
  tag: string;
  styles: StyleName[];
  options: OptionDef[];
};

export type SchemaDocs = Record<string, string>;

export type VersionInfo = { version: string; options: number };

export const assetUrl = (path: string): string =>
  new URL(`${import.meta.env.BASE_URL}${path}`, window.location.href).href;

async function getJson<T>(path: string): Promise<T> {
  const response = await fetch(assetUrl(path));
  if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
  return (await response.json()) as T;
}

export async function loadVersionIndex(): Promise<{ default: string | null; versions: VersionInfo[] }> {
  return getJson("schema/index.json");
}

export async function loadSchema(version: string): Promise<SchemaCore> {
  return getJson(`schema/${version}/core.json`);
}

export async function loadDocs(version: string): Promise<SchemaDocs> {
  return getJson(`schema/${version}/docs.json`);
}

/** The style payload sent to the wasm formatter: only user changes travel. */
export function buildStylePayload(style: StyleName, modified: Record<string, unknown> = {}): string {
  return JSON.stringify({ BasedOnStyle: style, ...modified });
}

/** Display value: explicit change, else the preset default, else unset. */
export function displayValue(
  option: OptionDef,
  style: StyleName,
  modified: Record<string, unknown>,
): unknown {
  if (Object.hasOwn(modified, option.key)) return modified[option.key];
  return option.defaults[style];
}
